import{decodeLogitsRow}from"./ctc.js";import{preprocessImage}from"./image-tensor.js";export async function recognizeCropsBatched(crops,ctx,charactersDictionary){let targetHeight=ctx.options.imageHeight??48;let batchSize=Math.max(1,ctx.options.recBatchSize??6);let dict=charactersDictionary??ctx.options.charactersDictionary??[];let spaceRecovery=ctx.options.spaceRecovery??false;let imageProcessor=ctx.engine==="opencv"?ctx.platform.imageProcessor:undefined;let prepped=await Promise.all(crops.map((crop)=>preprocessImage(crop,targetHeight,imageProcessor,ctx.platform.canvas.createProcessor.bind(ctx.platform.canvas))));let order=prepped.map((_,i)=>i).sort((a,b)=>{let wa=prepped[a]?.tensorWidth??0;let wb=prepped[b]?.tensorWidth??0;return wa-wb});let results=Array.from({length:crops.length});for(let start=0;start<order.length;start+=batchSize){let chunk=order.slice(start,start+batchSize);let maxWidth=Math.max(...chunk.map((i)=>prepped[i]?.tensorWidth??1));let channelSize=targetHeight*maxWidth;let stacked=new Float32Array(chunk.length*3*channelSize);chunk.forEach((cropIndex,row)=>{let p=prepped[cropIndex];if(!p)return;let rowBase=row*3*channelSize;for(let c=0;c<3;c++){for(let y=0;y<targetHeight;y++){let src=(c*targetHeight+y)*p.tensorWidth;let dst=rowBase+(c*targetHeight+y)*maxWidth;stacked.set(p.imageTensor.subarray(src,src+p.tensorWidth),dst);let edge=p.imageTensor[src+p.tensorWidth-1]??0;stacked.fill(edge,dst+p.tensorWidth,dst+maxWidth)}}});let inputTensor;try{inputTensor=new ctx.platform.ort.Tensor("float32",stacked,[chunk.length,3,targetHeight,maxWidth]);let output=await ctx.runInference(inputTensor);const[,seqLen,numClasses]=output.dims;let data=output.data;let rowSize=(seqLen??0)*(numClasses??0);chunk.forEach((cropIndex,row)=>{let widthShare=(prepped[cropIndex]?.tensorWidth??maxWidth)/maxWidth;let validSeq=Math.max(1,Math.min(seqLen??0,Math.ceil((seqLen??0)*widthShare)));results[cropIndex]=decodeLogitsRow(data.subarray(row*rowSize,row*rowSize+validSeq*(numClasses??0)),validSeq,numClasses??0,dict,spaceRecovery)})}finally{inputTensor?.dispose()}}return results}export function supportsDynamicBatch(session){let meta=session.inputMetadata;let dim=meta?.[0]?.shape?.[0];return typeof dim!=="number"||dim<0}